//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands (`::error::`,
//! `::warning::`, `::notice::`) so that CI runs surface annotations directly
//! in pull request diffs.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic becomes a single `::error::`, `::warning::`, or `::notice::`
/// line that GitHub Actions parses into a file annotation.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }
}

impl Default for GithubActionsFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl GithubActionsFormatter {
    /// Map severity to the GitHub Actions workflow command name.
    fn command_name(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let cmd = Self::command_name(diag.severity);

            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));

                if span.end_line != span.start_line {
                    params.push(format!("endLine={}", span.end_line));
                }

                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }
            }

            params.push(format!("title={}", diag.rule_id.0));

            let params_str = params.join(",");
            writeln!(writer, "::{cmd} {params_str}::{}", diag.message)?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn emits_error_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency detected",
        )
        .with_span(Span::line("config.yml", 15))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains(
            "::error file=config.yml,line=15,title=circular-dependency::Circular dependency detected"
        ));
    }

    #[test]
    fn emits_warning_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("app-name"),
            Severity::Warning,
            "App name contains spaces",
        )
        .with_span(Span::line("config.yml", 3))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output
            .contains("::warning file=config.yml,line=3,title=app-name::App name contains spaces"));
    }

    #[test]
    fn emits_notice_for_hints() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("style"),
            Severity::Hint,
            "Consider using snake_case",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::notice title=style::Consider using snake_case"));
    }

    #[test]
    fn includes_column_when_not_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "Bad value")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::error file=config.yml,line=10,col=5,title=test::Bad value"));
    }

    #[test]
    fn includes_end_line_when_multiline() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "Bad block")
                    .with_span(Span::new("config.yml", 10, 1, 15, 1)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::error file=config.yml,line=10,endLine=15,title=test::Bad block"));
    }

    #[test]
    fn omits_location_when_no_span() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Error,
            "General error",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::error title=test::General error"));
    }

    #[test]
    fn includes_title_from_rule_id() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency detected",
        )
        .with_span(Span::line("config.yml", 5))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("title=circular-dependency"));
    }

    #[test]
    fn handles_multiple_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "First error")
                .with_span(Span::line("config.yml", 1)),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "A warning")
                .with_span(Span::line("config.yml", 5)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 2);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
    }

    #[test]
    fn handles_empty_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.is_empty());
    }

    #[test]
    fn default_impl_works() {
        let formatter = GithubActionsFormatter::default();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.is_empty());
    }
}
